/bin/zsh -lc "cat > evidence/read_xls.py <<'PY'
import struct as s,json
from pathlib import Path
b=Path('保護統計_正誤_001265298.xls').read_bytes()
u16=lambda b,o=0:s.unpack_from('<H',b,o)[0]
u32=lambda b,o=0:s.unpack_from('<I',b,o)[0]
ss=1<<u16(b,30)
sec=lambda i:b[(i+1)*ss:(i+2)*ss]
dif=list(s.unpack_from('<109I',b,76)); fat=[]
for i in dif:
 if i<0xfffffffa: fat+=list(s.unpack('<%dI'%(ss//4),sec(i)))
def chain(i):
 out=b'';seen=set()
 while i<0xfffffffa and i not in seen:
  seen.add(i);out+=sec(i);i=fat[i]
 return out
d=chain(u32(b,48)); entries=[]
for o in range(0,len(d),128):
 x=d[o:o+128];n=u16(x,64)
 if n: entries.append((x[:n-2].decode('utf-16le'),u32(x,116),s.unpack_from('<Q',x,120)[0]))
print(entries)
name,start,size=next(x for x in entries if x[0] in ('Workbook','Book'))
w=chain(start)[:size]
recs=[];p=0
while p+4<=len(w):
 t,n=s.unpack_from('<HH',w,p);recs.append((p,t,w[p+4:p+4+n]));p+=4+n
sheets=[];strings=[]
for p,t,x in recs:
 if t==0x85:
  n=x[6]; wide=x[7]&1;sheets.append((u32(x),x[8:8+n*(2 if wide else 1)].decode('utf-16le' if wide else 'latin1')))
 if t==0xfc:
  print('SST bytes',len(x),'unique',u32(x,4))
  # Segmented reader handles CONTINUE boundaries inside strings.
  idx=next(i for i,r in enumerate(recs) if r[0]==p);chunks=[x];j=idx+1
  while j<len(recs) and recs[j][1]==0x3c: chunks.append(recs[j][2]);j+=1
  ci=0;pos=8
  def read(n):
   global ci,pos
   out=b''
   while n:
    if pos==len(chunks[ci]):ci+=1;pos=0
    k=min(n,len(chunks[ci])-pos);out+=chunks[ci][pos:pos+k];pos+=k;n-=k
   return out
  for _ in range(u32(x,4)):
   n=s.unpack('<H',read(2))[0];f=read(1)[0];rich=s.unpack('<H',read(2))[0] if f&8 else 0;ext=s.unpack('<I',read(4))[0] if f&4 else 0
   wide=f&1;v='';left=n
   while left:
    if pos==len(chunks[ci]):ci+=1;pos=0;wide=read(1)[0]&1
    k=min(left,(len(chunks[ci])-pos)//(2 if wide else 1))
    v+=read(k*(2 if wide else 1)).decode('utf-16le' if wide else 'latin1');left-=k
   read(rich*4+ext);strings.append(v)
def col(c):
 out=''
 while c>=0:out=chr(65+c%26)+out;c=c//26-1
 return out
out=[]
for si,(start,name) in enumerate(sheets):
 end=sheets[si+1][0] if si+1<len(sheets) else len(w)
 for p,t,x in recs:
  if not start<=p<end:continue
  v=None
  if t==0xfd:v=strings[u32(x,6)]
  elif t==0x203:v=s.unpack_from('<d',x,6)[0]
  elif t==0x27e:
   z=u32(x,6);v=(s.unpack('<i',s.pack('<I',z))[0]>>2) if z&2 else s.unpack('<d',s.pack('<II',0,z&0xfffffffc))[0]
   if z&1:v/=100
  if v is not None:out.append({'sheet':name,'cell':col(u16(x,2))+str(u16(x)+1),'value':v})
Path('evidence/xls_cells.json').write_text(json.dumps(out,ensure_ascii=False,indent=2))
for x in out:
 if any(k in str(x['value']) for k in ['6,864','6,866','6864','6866','表38','2016','平成28','平成２８']):print(x)
